head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.getToday = function() {
    var date = new Date();
    var dd = date.getDate() > 9 ? date.getDate() : '0' + date.getDate();
    var mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    var yy = date.getFullYear();
    var today = yy + '-' + mm + '-' + dd;
    return today;
}
scwin.compareDate = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_1").innerText == scwin.getToday() + " 00:00:00";
}
scwin.setVal = function() {
    scwin.fireDbClick(WebSquare.wUnit.getDomById('gridView1_cell_0_1'));
}
